Q: Connecting the ribbons to funnel chart bars cleanly A: <p>Make both the ribbons and bars quantitative and use a calculated <code>stageBottom</code> and <code>stageTop</code> with a <a href="https://vega.github.io/vega-lite/docs/parameter.html#in-expression-strings" rel="nofollow noreferrer">parameter</a> <code>stage_width</code> for demonstrantion purposes; this is similar to what alluvial / sankey charts do <a href="https://stackoverflow.com/a/73191233/28479453">1</a></p>
<pre><code>{
  &quot;params&quot;: [
    { &quot;name&quot;: &quot;stage_width&quot;, &quot;value&quot;: 0.2,
      &quot;bind&quot;: {&quot;input&quot;: &quot;range&quot;, &quot;min&quot;: 0.1, &quot;max&quot;: 0.4, &quot;step&quot;: 0.05} }
  ],
  &quot;data&quot;: {&quot;name&quot;: &quot;dataset&quot;,
  &quot;values&quot;: [
    {&quot;AttSort&quot;: &quot;1. Applications&quot;, &quot;Domicile&quot;: &quot;UK&quot;, &quot;Sum of Value&quot;: 19000},
    {&quot;AttSort&quot;: &quot;1. Applications&quot;, &quot;Domicile&quot;: &quot;EU&quot;, &quot;Sum of Value&quot;: 23000},
    {&quot;AttSort&quot;: &quot;1. Applications&quot;, &quot;Domicile&quot;: &quot;International&quot;, &quot;Sum of Value&quot;: 34000},
    {&quot;AttSort&quot;: &quot;1. Applications&quot;, &quot;Domicile&quot;: &quot;Islands&quot;, &quot;Sum of Value&quot;: 27000},

    {&quot;AttSort&quot;: &quot;2. Offers&quot;, &quot;Domicile&quot;: &quot;UK&quot;, &quot;Sum of Value&quot;: 15000},
    {&quot;AttSort&quot;: &quot;2. Offers&quot;, &quot;Domicile&quot;: &quot;EU&quot;, &quot;Sum of Value&quot;: 12000},
    {&quot;AttSort&quot;: &quot;2. Offers&quot;, &quot;Domicile&quot;: &quot;International&quot;, &quot;Sum of Value&quot;: 25000},
    {&quot;AttSort&quot;: &quot;2. Offers&quot;, &quot;Domicile&quot;: &quot;Islands&quot;, &quot;Sum of Value&quot;: 19000},

    {&quot;AttSort&quot;: &quot;3. Acceptances (UF)&quot;, &quot;Domicile&quot;: &quot;UK&quot;, &quot;Sum of Value&quot;: 3700},
    {&quot;AttSort&quot;: &quot;3. Acceptances (UF)&quot;, &quot;Domicile&quot;: &quot;EU&quot;, &quot;Sum of Value&quot;: 3700},
    {&quot;AttSort&quot;: &quot;3. Acceptances (UF)&quot;, &quot;Domicile&quot;: &quot;International&quot;, &quot;Sum of Value&quot;: 6400},
    {&quot;AttSort&quot;: &quot;3. Acceptances (UF)&quot;, &quot;Domicile&quot;: &quot;Islands&quot;, &quot;Sum of Value&quot;: 5100},

    {&quot;AttSort&quot;: &quot;4. Enrolments&quot;, &quot;Domicile&quot;: &quot;UK&quot;, &quot;Sum of Value&quot;: 2800},
    {&quot;AttSort&quot;: &quot;4. Enrolments&quot;, &quot;Domicile&quot;: &quot;EU&quot;, &quot;Sum of Value&quot;: 2800},
    {&quot;AttSort&quot;: &quot;4. Enrolments&quot;, &quot;Domicile&quot;: &quot;International&quot;, &quot;Sum of Value&quot;: 4000},
    {&quot;AttSort&quot;: &quot;4. Enrolments&quot;, &quot;Domicile&quot;: &quot;Islands&quot;, &quot;Sum of Value&quot;: 4000}
  ]},
  &quot;height&quot;: 500,
  &quot;width&quot; : 800,
  &quot;transform&quot;: [
    {
      &quot;calculate&quot;: &quot;isDefined(datum['Academic Level']) ? datum['Academic Level'] : isDefined(datum['Department']) ? datum['Department'] : isDefined(datum['Faculty']) ? datum['Faculty'] : isDefined(datum['Domicile']) ? datum['Domicile'] : isDefined(datum['Disability']) ? datum['Disability'] : isDefined(datum['Fee Status']) ? datum['Fee Status'] : isDefined(datum['Gender']) ? datum['Gender'] : isDefined(datum['IMD']) ? datum['IMD'] : isDefined(datum['POLAR4_quintile']) ? datum['POLAR4_quintile'] : isDefined(datum['MOA']) ? datum['MOA'] : 'Other'&quot;,
      &quot;as&quot;: &quot;SelectedLegend&quot;
    },
    { &quot;window&quot;: [{&quot;op&quot;: &quot;dense_rank&quot;, &quot;as&quot;: &quot;stageNum&quot;}], &quot;sort&quot;: [{&quot;field&quot;: &quot;AttSort&quot;}] },
    {
      &quot;stack&quot;: &quot;Sum of Value&quot;,
      &quot;groupby&quot;: [&quot;AttSort&quot;],
      &quot;as&quot;: [&quot;x0&quot;, &quot;x1&quot;],
      &quot;offset&quot;: &quot;center&quot;,
      &quot;sort&quot;: [{&quot;field&quot;: &quot;SelectedLegend&quot;, &quot;order&quot;: &quot;descending&quot;}]
    },
    {&quot;calculate&quot;: &quot;(datum.x0 + datum.x1) / 2&quot;, &quot;as&quot;: &quot;label_midpoint&quot;},
    /* create upper and lower points for the ribbons */
    {&quot;calculate&quot;: &quot;datum.stageNum - stage_width&quot;, &quot;as&quot;: &quot;stageTop&quot;},
    {&quot;calculate&quot;: &quot;datum.stageNum + stage_width&quot;, &quot;as&quot;: &quot;stageBottom&quot;}
  ],
  &quot;layer&quot;: [
    {
      &quot;description&quot;: &quot;RIBBONS&quot;,
      &quot;transform&quot;: [
        {&quot;calculate&quot;: &quot;[datum.stageTop, datum.stageBottom]&quot;, &quot;as&quot;: &quot;stagePosArr&quot;},
        {&quot;flatten&quot;: [&quot;stagePosArr&quot;], &quot;as&quot;: [&quot;stagePos&quot;]}
      ],
      &quot;mark&quot;: {&quot;type&quot;: &quot;area&quot;, &quot;interpolate&quot;: &quot;monotone&quot;, &quot;opacity&quot;: 0.6, &quot;orient&quot;: &quot;horizontal&quot;},
      &quot;encoding&quot;: {
        &quot;y&quot;: {
          &quot;field&quot;: &quot;stagePos&quot;,
          &quot;type&quot;: &quot;quantitative&quot;,
          &quot;scale&quot;: {&quot;reverse&quot;: true},
          &quot;axis&quot;: {&quot;labels&quot;: false} /* disable quantative labels */          
        },
        &quot;x&quot;: {&quot;field&quot;: &quot;x0&quot;, &quot;type&quot;: &quot;quantitative&quot;},
        &quot;x2&quot;: {&quot;field&quot;: &quot;x1&quot;},
        &quot;detail&quot;: {&quot;field&quot;: &quot;SelectedLegend&quot;},
        &quot;color&quot;: {&quot;field&quot;: &quot;SelectedLegend&quot;, &quot;type&quot;: &quot;nominal&quot;, &quot;sort&quot;: &quot;descending&quot;}
      }
    },
    {
      &quot;description&quot;: &quot;Y LABS&quot;,
      &quot;mark&quot;: {&quot;type&quot;: &quot;text&quot;, &quot;align&quot;: &quot;right&quot;, &quot;dx&quot;: -6, &quot;fontSize&quot;: 12}, /* dx is the distance between y-labs and plot */ 
      &quot;encoding&quot;: {
        &quot;y&quot;: {&quot;field&quot;: &quot;stageNum&quot;, &quot;type&quot;: &quot;quantitative&quot;, &quot;scale&quot;: {&quot;reverse&quot;: true}},
        &quot;x&quot;: {&quot;value&quot;: 0},
        &quot;text&quot;: {&quot;field&quot;: &quot;AttSort&quot;, &quot;type&quot;: &quot;nominal&quot;}
      }
    },
    {
      &quot;description&quot;: &quot;BARS&quot;,
      &quot;mark&quot;: {&quot;type&quot;: &quot;bar&quot;},
      &quot;encoding&quot;: {
        &quot;y&quot;: {&quot;field&quot;: &quot;stageTop&quot;, &quot;type&quot;: &quot;quantitative&quot;},
        &quot;y2&quot;: {&quot;field&quot;: &quot;stageBottom&quot;, &quot;type&quot;: &quot;quantitative&quot;},
        &quot;x&quot;: {&quot;field&quot;: &quot;x0&quot;, &quot;type&quot;: &quot;quantitative&quot;},
        &quot;x2&quot;: {&quot;field&quot;: &quot;x1&quot;},
        &quot;color&quot;: {&quot;field&quot;: &quot;SelectedLegend&quot;, &quot;type&quot;: &quot;nominal&quot;, &quot;sort&quot;: &quot;descending&quot;}
      }
    },
    {
      &quot;description&quot;: &quot;DATA LABELS&quot;,
      &quot;mark&quot;: {&quot;type&quot;: &quot;text&quot;, &quot;baseline&quot;: &quot;middle&quot;, &quot;fontSize&quot;: 10, &quot;fontWeight&quot;: &quot;bold&quot;, &quot;color&quot;: &quot;white&quot;},
      &quot;encoding&quot;: {
        &quot;y&quot;: {
          &quot;field&quot;: &quot;stageNum&quot;, &quot;type&quot;: &quot;quantitative&quot;, &quot;scale&quot;: {&quot;reverse&quot;: true}
        },
        &quot;x&quot;: {&quot;field&quot;: &quot;label_midpoint&quot;, &quot;type&quot;: &quot;quantitative&quot;},
        &quot;detail&quot;: {&quot;field&quot;: &quot;SelectedLegend&quot;},
        &quot;text&quot;: {&quot;field&quot;: &quot;Sum of Value&quot;, &quot;type&quot;: &quot;quantitative&quot;, &quot;format&quot;: &quot;.2s&quot;}
      }
    }
  ],
  &quot;config&quot;: {
    &quot;view&quot;: {&quot;stroke&quot;: &quot;transparent&quot;},
    &quot;axis&quot;: {&quot;grid&quot;: false, &quot;domain&quot;: false, &quot;ticks&quot;: false, &quot;title&quot;: null, &quot;labelFontSize&quot;: 10}
  }
}
</code></pre>
